using System;using System.IO;using System.Reflection;using UnityEditor;using UnityEngine;
namespace Staff.Traversal.Editor {
[InitializeOnLoad] public static class TangentContourReview {
 const string W="Library/TangentMath/";static TangentEquationUI ui;
 static TangentContourReview(){EditorApplication.update+=Poll;}
 static void Poll(){if(!EditorApplication.isCompiling&&!EditorApplication.isUpdating&&File.Exists(W+"demo.request")){File.Delete(W+"demo.request");try{Demo();}catch(Exception e){File.WriteAllText(W+"demo-error.txt",e.ToString());}}if(EditorApplication.isCompiling||EditorApplication.isUpdating||!File.Exists(W+"capture.request"))return;File.Delete(W+"capture.request");try{Run();}catch(Exception e){File.WriteAllText(W+"capture-error.txt",e.ToString());}}
 static T Field<T>(string name)=>(T)typeof(TangentEquationUI).GetField(name,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(ui);
 static void Run(){File.WriteAllText(W+"capture.txt","");var root=new GameObject("Temporary tangent review");var cameraObject=new GameObject("Temporary tangent camera");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.transform.SetPositionAndRotation(new Vector3(5,0,-10),Quaternion.identity);camera.fieldOfView=60;
 try{ui=root.AddComponent<TangentEquationUI>();ui.enabled=false;ui.BeginAim(camera,camera.pixelRect.center);ui.Present(true,camera,new Vector3(0,2,0),new Vector3(5,-.01f,0));ui.Render(.26f);Capture("write");ui.Render(.65f);Capture("symbolic");ui.Lock(new Vector3(0,2,0),new Vector3(5,-.01f,0));ui.Render(.2f);Capture("contour-transform");ui.Render(.85f);Capture("numeric");var ink=Field<TangentContourGraphic>("graphic");ink.color=Color.black;ink.weight=1.35f;ink.SetVerticesDirty();Capture("imaginary");ink.color=Color.white;ink.weight=1;ui.Dismiss();ui.Render(.175f);Capture("uncreate");ui.Render(.4f);if(ui.IsVisible)throw new Exception("Uncreate failed to finish");ui.BeginAim(camera,camera.pixelRect.center);ui.Render(.1f);ui.Dismiss();ui.Render(.4f);if(ui.IsVisible)throw new Exception("Cancel during Write failed");File.AppendAllText(W+"capture.txt","PASS interrupted Write and completed Uncreate\n");}
 finally{var overlay=ui?Field<Canvas>("overlay"):null;if(overlay)UnityEngine.Object.DestroyImmediate(overlay.gameObject);UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(cameraObject);}}
 static void Demo(){Directory.CreateDirectory(W+"frames");var root=new GameObject("Temporary demo");var cameraObject=new GameObject("Temporary demo camera");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.transform.position=new Vector3(5,0,-30);
 try{ui=root.AddComponent<TangentEquationUI>();ui.enabled=false;ui.BeginAim(camera,camera.pixelRect.center);ui.Present(true,camera,new Vector3(0,2,0),new Vector3(5,-.01f,0));for(int i=0;i<120;i++){if(i==36)ui.Lock(new Vector3(0,2,0),new Vector3(5,-.01f,0));if(i==99)ui.Dismiss();ui.Render(1f/30);if(ui.IsVisible)Capture("frames/"+i.ToString("D4"));}File.WriteAllText(W+"demo-complete.txt","120 ticks: Write, contour substitution, Uncreate");}
 finally{var overlay=ui?Field<Canvas>("overlay"):null;if(overlay)UnityEngine.Object.DestroyImmediate(overlay.gameObject);UnityEngine.Object.DestroyImmediate(root);UnityEngine.Object.DestroyImmediate(cameraObject);}}
 static void Capture(string name){Canvas.ForceUpdateCanvases();var graphic=Field<TangentContourGraphic>("graphic");var mesh=UnityEngine.Object.Instantiate(graphic.canvasRenderer.GetMesh());if(mesh.vertexCount==0)throw new Exception("Empty UI geometry "+name);var go=new GameObject("Temporary equation mesh");go.layer=31;go.transform.position=new Vector3(10000,0,0);go.AddComponent<MeshFilter>().sharedMesh=mesh;var material=new Material(Shader.Find("UI/Default"));go.AddComponent<MeshRenderer>().sharedMaterial=material;var cameraObject=new GameObject("Temporary equation capture");var camera=cameraObject.AddComponent<Camera>();camera.enabled=false;camera.orthographic=true;camera.orthographicSize=48;camera.cullingMask=1<<31;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.03f,.035f,.045f);camera.transform.position=go.transform.position+Vector3.back*10;var rt=new RenderTexture(1280,384,24);var prior=RenderTexture.active;Texture2D image=null;
 try{RenderTexture.active=rt;GL.Clear(true,true,name=="imaginary"?Color.white:new Color(.03f,.035f,.045f));GL.PushMatrix();GL.LoadIdentity();float halfH=60;GL.LoadProjectionMatrix(Matrix4x4.Ortho(-halfH*1280/384,halfH*1280/384,-halfH,halfH,-1,1));material.SetPass(0);Graphics.DrawMeshNow(mesh,Matrix4x4.identity);GL.PopMatrix();image=new Texture2D(rt.width,rt.height,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);image.Apply();File.WriteAllBytes(W+name+".png",image.EncodeToPNG());File.AppendAllText(W+"capture.txt","PASS "+name+": "+mesh.vertexCount+" UI vertices\n");}
 finally{RenderTexture.active=prior;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(go);UnityEngine.Object.DestroyImmediate(cameraObject);UnityEngine.Object.DestroyImmediate(mesh);UnityEngine.Object.DestroyImmediate(material);UnityEngine.Object.DestroyImmediate(rt);if(image)UnityEngine.Object.DestroyImmediate(image);}}
 }
}
